import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, vec4, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Vector3 } = ctx.THREE;

  const root = new Group();
  root.name = 'collection-card-2';

  const ink = new ctx.THREE.Color('#16161d');
  const surface = new ctx.THREE.Color('#0b0b10');

  // Stage: vertical gradient backdrop
  const stageGeom = new PlaneGeometry(7, 6);
  const stageMat = new MeshBasicNodeMaterial({
    side: ctx.THREE.DoubleSide,
    transparent: true,
  });
  const u = uv();
  const cTop = color(surface);
  const cBot = color(ink);
  const grad = mix(cTop, cBot, u.y);
  stageMat.colorNode = vec4(grad, 1.0);
  const stage = new Mesh(stageGeom, stageMat);
  stage.position.set(0, 0, -2.5);
  root.add(stage);

  // Textured card
  const cardW = 2.0;
  const cardH = 2.0 / (512 / 320); // ≈1.25
  const cardGeom = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({
    side: ctx.THREE.DoubleSide,
    transparent: true,
  });
  const card = new Mesh(cardGeom, cardMat);
  card.position.set(0, 0, 0);
  root.add(card);

  // Ground shadow plane
  const shadowGeom = new PlaneGeometry(cardW * 1.35, cardH * 1.35);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: ctx.THREE.DoubleSide,
  });
  const shadowGrad = mix(
    color(surface).setRGB(0.11, 0.11, 0.15),
    color(surface).setRGB(0.0, 0.0, 0.0),
    uv().y
  );
  shadowMat.colorNode = vec4(shadowGrad, 0.5 * (1.0 - uv().y));
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -cardH / 2 - 0.1, 0.2);
  root.add(shadow);

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        tex.colorSpace = ctx.THREE.SRGBColorSpace;
        cardMat.colorNode = texture(tex, uv());
        cardMat.needsUpdate = true;
      })
      .catch(() => {
        // fallback: keep gradient-like tint if texture fails
      });
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    stageGeom.dispose();
    stageMat.dispose();
    cardGeom.dispose();
    cardMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
  };

  return root;
}
